  aplicaciones_en = ARRAY(SELECT jsonb_array_elements_text($j$["Clinical decision-making","Patient safety"]$j$::jsonb)),
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Captura SpO2, pulso, PANI y temperatura para adultos, pediátricos y neonatos.","Comunicación bidireccional por red cableada o inalámbrica y lector de código de barras compatible.","Ligero y portátil: 3.5 kg con batería."],"beneficios_en":["Captures SpO2, pulse, NIBP and temperature for adults, paediatrics and neonates.","Two-way wired or wireless network communication and compatible barcode reader.","Lightweight and portable: 3.5 kg with battery."],"valor_es":"Un monitor de signos vitales portátil con conectividad a estación central, con dos años de garantía.","valor_en":"A portable vital signs monitor with central station connectivity, with a two-year warranty.","preguntas_frecuentes_es":[{"q":"¿Qué parámetros mide?","a":"SpO2, frecuencia de pulso, presión arterial no invasiva y temperatura."},{"q":"¿Cuánto pesa?","a":"3.5 kg con batería; 200.8 x 241 x 189 mm."},{"q":"¿Se conecta a red?","a":"Sí, puerto Ethernet RJ-45 y comunicación por red cableada o inalámbrica."},{"q":"¿Dónde obtengo la ficha técnica?","a":"Descargue el PDF oficial de Advanced Instrumentations en esta landing (modelo VSM-300)."},{"q":"¿Cómo solicito cotización a IME?","a":"Indique el modelo exacto (VSM-300), el área clínica y las aplicaciones previstas (Toma de decisiones clínicas; Seguridad del paciente); IME confirma disponibilidad, ficha técnica y condiciones en Colombia."},{"q":"¿Dónde descargo la ficha técnica de Monitor Multiparamétrico Básico?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Advanced Instrumentations (en español)."}],"preguntas_frecuentes_en":[{"q":"Which parameters does it measure?","a":"SpO2, pulse rate, non-invasive blood pressure and temperature."},{"q":"How much does it weigh?","a":"3.5 kg with battery; 200.8 x 241 x 189 mm."},{"q":"Does it connect to a network?","a":"Yes, RJ-45 Ethernet and wired or wireless network communication."},{"q":"Where is the datasheet?","a":"Download the official Advanced Instrumentations PDF on this page (model VSM-300)."},{"q":"How do I get a quote?","a":"Provide exact model (VSM-300), clinical area and intended applications (Clinical decision-making; Patient safety); IME confirms availability, datasheet and terms in Colombia."},{"q":"Where can I download the Basic Multiparameter Monitor datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Advanced Instrumentations PDF (in Spanish)."}],"seo_keywords_es":["monitor de signos vitales","monitor VSM-300","monitor de signos vitales portátil","monitor Advanced","monitor de signos vitales Colombia","ficha técnica VSM-300","Monitor de signos vitales VSM-300","Monitor de signos vitales VSM-300 Advanced Instrumentations","VSM-300 Colombia","equipo médico IME"],"seo_keywords_en":["vital signs monitor","VSM-300 monitor","portable vital signs monitor","Advanced monitor","vital signs monitor Colombia","VSM-300 datasheet","VSM-300 vital signs monitor","VSM-300 vital signs monitor Advanced Instrumentations","VSM-300 Colombia","IME medical equipment"],"ficha_fabricante":{"fabricante":"Advanced Instrumentations","idioma":"es","url_origen":"https://www.i-me.com.co","descargada":"2026-10-18","sin_pdf":false}}$j$::jsonb
