  aplicaciones_es = ARRAY(SELECT jsonb_array_elements_text($j$["Neonatología","Cuidados intensivos neonatales"]$j$::jsonb)),
  aplicaciones_en = ARRAY(SELECT jsonb_array_elements_text($j$["Neonatology","Neonatal intensive care"]$j$::jsonb)),
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Control servo por piel, modo manual y precalentamiento inteligente para estabilizar la temperatura del bebé.","Reflector articulable y bandeja para rayos X que permiten estudios sin retirar al paciente.","Contador de tiempo y de Apgar, flujómetros de oxígeno y aire y panel de gas con aspiración y resucitador.","Dos opciones de fototerapia: lámpara de 5 focos LED o fototerapia inversa."],"beneficios_en":["Skin servo control, manual mode and intelligent pre-warming to stabilize the baby's temperature.","Articulating reflector and X-ray tray that allow imaging without moving the patient.","Time and Apgar counters, oxygen and air flowmeters and a gas panel with suction and resuscitator.","Two phototherapy options: 5-LED lamp or reverse phototherapy."],"valor_es":"Una cuna de calor radiante con servocontrol, acceso a rayos X y fototerapia integrable, con dos años de garantía del fabricante.","valor_en":"A radiant warmer with servo control, X-ray access and integrable phototherapy, with a two-year manufacturer warranty.","preguntas_frecuentes_es":[{"q":"¿Qué opciones de pantalla tiene?","a":"Tres: LCD a color, monitor monocromo y pantalla LED, según la ficha del fabricante."},{"q":"¿Se puede hacer fototerapia?","a":"Sí. Ofrece lámpara de fototerapia de 5 focos LED o fototerapia inversa como opciones."},{"q":"¿Qué accesorios son opcionales?","a":"Mezclador aire/oxígeno, colchón térmico, oxímetro de pulso (SpO2), kit eléctrico de altura y transporte, CPAP y balanza."},{"q":"¿Dónde obtengo la ficha técnica?","a":"Descargue el PDF oficial de Advanced Instrumentations en esta landing (modelo A4051)."},{"q":"¿Cómo solicito cotización a IME?","a":"Indique el modelo exacto (A4051), el área clínica y las aplicaciones previstas (Neonatología; Cuidados intensivos neonatales); IME confirma disponibilidad, ficha técnica y condiciones en Colombia."},{"q":"¿Dónde descargo la ficha técnica de Cuna de Calor Radiante Neonatal Servo?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Advanced Instrumentations (en español)."}],"preguntas_frecuentes_en":[{"q":"What display options does it have?","a":"Three: colour LCD, monochrome monitor and LED display, according to the manufacturer datasheet."},{"q":"Can phototherapy be performed?","a":"Yes. It offers a 5-LED phototherapy lamp or reverse phototherapy as options."},{"q":"Which accessories are optional?","a":"Air/oxygen blender, thermal mattress, pulse oximeter (SpO2), electric height/transport kit, CPAP and scale."},{"q":"Where is the datasheet?","a":"Download the official Advanced Instrumentations PDF on this page (model A4051)."},{"q":"How do I get a quote?","a":"Provide exact model (A4051), clinical area and intended applications (Neonatology; Neonatal intensive care); IME confirms availability, datasheet and terms in Colombia."},{"q":"Where can I download the Servo Neonatal Radiant Warmer datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Advanced Instrumentations PDF (in Spanish)."}],"seo_keywords_es":["cuna de calor radiante","cuna de calor radiante A4051","cuna radiante neonatal","cuna de calor neonatología","equipo de cuidados intensivos neonatales","cuna de calor Colombia","ficha técnica A4051","Cuna de calor radiante A4051 Advanced Instrumentations","A4051 Colombia","equipo médico IME"],"seo_keywords_en":["radiant warmer","A4051 radiant warmer","neonatal radiant warmer","neonatal care radiant bed","NICU equipment","radiant warmer Colombia","A4051 datasheet","A4051 radiant warmer Advanced Instrumentations","A4051 Colombia","IME medical equipment"],"ficha_fabricante":{"fabricante":"Advanced Instrumentations","idioma":"es","url_origen":"https://www.i-me.com.co","descargada":"2026-10-18","sin_pdf":false}}$j$::jsonb
